{"command":"cd sb/trespass && python3 -c "
from PIL import Image
import glob
sheets=sorted(glob.glob('m*.jpg'))
# each sheet: 320x180 grid 3x3 of 320x180?? L3: width 320 height 180, cols=3 rows=3 per sheet, cell 320x180
cells=[]
for s in sheets:
    im=Image.open(s)
    w,h=im.size
    cw,ch=w//3,h//3
    for r in range(3):
        for c in range(3):
            cell=im.crop((c*cw,r*ch,(c+1)*cw,(r+1)*ch)).resize((1,1))
            cells.append(cell.getpixel((0,0)))
print('cells:',len(cells))
# save as a thin strip image, and also print hex every 10 cells
out=Image.new('RGB',(len(cells),40))
for i,p in enumerate(cells):
    for y in range(40): out.putpixel((i,y),p)
out.save('trespass_strip.png')
for i in range(0,len(cells),10):
    p=cells[i]; print(f'{i*10//60:>4}s x={i:3d}', p)
""}

